struct Data {
    value: i32,
    label: String,
}

fn main() {
    let mut data = Data {
        value: 10,
        label: "test".to_string(),
    };

    // Immutable borrow to read
    let label_ref = &data.label;
    let _ = label_ref; // Use the reference to ensure it's valid

    // Mutable borrow to modify
    let value_ref = &mut data.value;
    *value_ref += 5;

    // Assert final value
    assert_eq!(data.value, 15);

    println!("Ownership test passed");
}
